import gurobipy as gp
from gurobipy import GRB
products = []
profit = {}
space = {}
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('products.csv'):
        v = rec['values']
        name = v['item_name']
        products.append(name)
        profit[name] = int(v['item_value'])
        space[name] = int(v['resource_requirement'])
    elif rec['source'].endswith('capacity.csv'):
        capacity = int(rec['values']['resource_capacity'])
if len(products) == 0 or len(profit) != len(products) or len(space) != len(products):
    raise ValueError('Missing or incomplete product data.')
m = gp.Model('BakeryOrder')
x_vars = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((profit[p] * x_vars[p] for p in products)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((space[p] * x_vars[p] for p in products)) <= capacity, name='storage')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')